    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ]
  }
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss emphasizes pairs where the advantage signal differs significantly relative to the cost gap, promoting better preference ordering by aligning high advantage with low cost gap. It leverages the advantage differences weighted by the cost gap to focus on impactful pairs, encouraging models to prefer options with higher advantage and lower associated costs.",
  "pseudocode": "score = mean over pairs of (ops.logsigmoid(extra['advantage_w'] - extra['advantage_l']) * (ops.log(extra['cost_gap']) + 1))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage_cost",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "cost_advantage_correlation",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "log", "mul", "add", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    advantage_w = extra[\"advantage_w\"]\n    advantage_l = extra[\"advantage_l\"]\n    cost_gap = extra[\"cost_gap\"]\n    weight = batch[\"weight\"]\n    diff_adv = sub(advantage_w, advantage_l)\n    cost_log = log(ops.clamp(cost_gap, min=1e-6))\n    pairwise_score = mul(logsigmoid(diff_adv), add(cost_log, 1))\n    loss = ops.mean(mul(pairwise_score, weight))\n    return loss"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss combines advantage signals with cost gaps to promote better preference ordering by emphasizing differences in advantage weighted by cost gaps, encouraging the model to prioritize higher advantage pairs with larger cost gaps. Using logsigmoid on advantage differences helps to smoothly transition between preferences, and weighting by cost_gap ensures focus on impactful pairs.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l) * (cost_gap))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage_cost",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "cost_gap"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch.get('cost_gap', None)\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    sigmoid_diff = ops.logsigmoid(advantage_diff)\n    weighted = ops.mul(sigmoid_diff, cost_gap)\n    loss = ops.neg(ops.mean(weighted))\n    return loss"
}

